contract InvMutTest is Test {
    airPort c;

    function setUp() public { c = new airPort(); }

    function testFuzz_property(address from, uint256 v) public {
        vm.assume(from != address(0));
        Token token = new Token();
        address[] memory tos = new address[](1);
        tos[0] = address(token);
        bool ret = c.transfer(from, address(token), tos, v);
        assertTrue(ret, "successful transfer must return true");
